-- RH and organizational governance for AgriCapital 360 workspace.
create table if not exists public.workspace_job_descriptions (id uuid primary key default gen_random_uuid(),title text not null check(length(trim(title)) between 2 and 160),department text,purpose text not null,responsibilities jsonb not null default '[]'::jsonb check(jsonb_typeof(responsibilities)='array'),required_skills jsonb not null default '[]'::jsonb check(jsonb_typeof(required_skills)='array'),objectives jsonb not null default '[]'::jsonb check(jsonb_typeof(objectives)='array'),reports_to_role text,access_profile text not null default 'private' check(access_profile in ('private','employee','manager','hr')),status text not null default 'draft' check(status in ('draft','published','archived')),version integer not null default 1 check(version>0),created_by_profile_id uuid not null references public.profiles(id) on delete restrict,updated_by_profile_id uuid references public.profiles(id) on delete set null,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.workspace_job_assignments (id uuid primary key default gen_random_uuid(),profile_id uuid not null references public.profiles(id) on delete cascade,job_description_id uuid not null references public.workspace_job_descriptions(id) on delete restrict,effective_from date not null default current_date,effective_to date,assigned_by_profile_id uuid not null references public.profiles(id) on delete restrict,acknowledgement text not null default 'pending' check(acknowledgement in ('pending','acknowledged','questions')),acknowledged_at timestamptz,notes text,created_at timestamptz not null default now(),check(effective_to is null or effective_to>=effective_from));
create unique index if not exists workspace_job_assignments_active_unique on public.workspace_job_assignments(profile_id) where effective_to is null;
create index if not exists workspace_job_assignments_job_idx on public.workspace_job_assignments(job_description_id,profile_id);
create table if not exists public.workspace_reporting_lines (id uuid primary key default gen_random_uuid(),profile_id uuid not null references public.profiles(id) on delete cascade,manager_profile_id uuid references public.profiles(id) on delete set null,department text,team_id uuid references public.equipes(id) on delete set null,valid_from date not null default current_date,valid_to date,assigned_by_profile_id uuid not null references public.profiles(id) on delete restrict,created_at timestamptz not null default now(),check(profile_id<>manager_profile_id),check(valid_to is null or valid_to>=valid_from));
create unique index if not exists workspace_reporting_lines_active_unique on public.workspace_reporting_lines(profile_id) where valid_to is null;
create index if not exists workspace_reporting_lines_manager_idx on public.workspace_reporting_lines(manager_profile_id) where valid_to is null;
alter table public.workspace_job_descriptions enable row level security; alter table public.workspace_job_assignments enable row level security; alter table public.workspace_reporting_lines enable row level security;
drop policy if exists workspace_job_descriptions_read on public.workspace_job_descriptions;
create policy workspace_job_descriptions_read on public.workspace_job_descriptions for select to authenticated using(status='published' and access_profile='employee' or created_by_profile_id=public.internal_current_profile_id() or exists(select 1 from public.workspace_job_assignments a where a.job_description_id=id and a.profile_id=public.internal_current_profile_id()) or exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','admin','administrateur','pdg','dg','directeur_general','directeur général')));
drop policy if exists workspace_job_descriptions_manage on public.workspace_job_descriptions;
create policy workspace_job_descriptions_manage on public.workspace_job_descriptions for all to authenticated using(exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','admin','administrateur','pdg','dg','directeur_general','directeur général'))) with check(exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','admin','administrateur','pdg','dg','directeur_general','directeur général')));
drop policy if exists workspace_job_assignments_read on public.workspace_job_assignments;
create policy workspace_job_assignments_read on public.workspace_job_assignments for select to authenticated using(profile_id=public.internal_current_profile_id() or exists(select 1 from public.workspace_reporting_lines rl where rl.profile_id=workspace_job_assignments.profile_id and rl.manager_profile_id=public.internal_current_profile_id() and rl.valid_to is null) or exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','admin','administrateur','pdg','dg','directeur_general','directeur général')));
drop policy if exists workspace_job_assignments_manage on public.workspace_job_assignments;
create policy workspace_job_assignments_manage on public.workspace_job_assignments for all to authenticated using(exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','admin','administrateur','pdg','dg','directeur_general','directeur général'))) with check(assigned_by_profile_id=public.internal_current_profile_id() and exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','admin','administrateur','pdg','dg','directeur_general','directeur général')));
drop policy if exists workspace_reporting_lines_read on public.workspace_reporting_lines;
create policy workspace_reporting_lines_read on public.workspace_reporting_lines for select to authenticated using(profile_id=public.internal_current_profile_id() or manager_profile_id=public.internal_current_profile_id() or exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','admin','administrateur','pdg','dg','directeur_general','directeur général')));
drop policy if exists workspace_reporting_lines_manage on public.workspace_reporting_lines;
create policy workspace_reporting_lines_manage on public.workspace_reporting_lines for all to authenticated using(exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','admin','administrateur','pdg','dg','directeur_general','directeur général'))) with check(assigned_by_profile_id=public.internal_current_profile_id() and exists(select 1 from public.user_roles ur join public.profiles p on p.user_id=ur.user_id where p.id=public.internal_current_profile_id() and lower(ur.role) in ('rh','responsable_rh','admin','administrateur','pdg','dg','directeur_general','directeur général')));
grant select,insert,update,delete on public.workspace_job_descriptions,public.workspace_job_assignments,public.workspace_reporting_lines to authenticated; revoke all on public.workspace_job_descriptions,public.workspace_job_assignments,public.workspace_reporting_lines from anon;
